(function(){
 const api=window.KHALASA_API_BASE_URL||location.origin;
 const headers=()=>({'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('khalasaStaffToken')||''}`});
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 adminTitles.security='صلاحيات الإدارة الرئيسية';
 document.querySelector('aside nav').insertAdjacentHTML('beforeend','<button data-admin-page="security" onclick="adminPage(\'security\',this);loadMainAdmins()">🔐 <span>صلاحيات الإدارة</span></button>');
 document.querySelector('.admin-actions').insertAdjacentHTML('beforeend','<button title="تسجيل الخروج" onclick="staffLogout()">خروج</button>');
 document.querySelector('main').insertAdjacentHTML('beforeend',`<section class="admin-page" id="admin-security"><div class="city-admin-layout"><form class="panel city-form" onsubmit="createMainAdmin(event)"><div class="panel-head"><div><h2>منح صلاحية اللوحة الرئيسية</h2><p>لن يستطيع الدخول إلا المالك أو مستخدم تضيفه هنا.</p></div></div><div class="city-form-grid"><label>الاسم الكامل<input id="mainAdminName" required></label><label>رقم الهاتف<input id="mainAdminPhone" pattern="01[0-9]{9}" required></label><label>رمز دخول مؤقت<input id="mainAdminCode" type="password" minlength="8" required></label></div><button class="primary">منح الصلاحية</button></form><section class="panel city-list"><div class="panel-head"><h2>المصرح لهم</h2><button onclick="loadMainAdmins()">↻ تحديث</button></div><div id="mainAdminsList"></div></section></div></section>`);
 const finance=document.getElementById('admin-finance');
 finance.innerHTML=`<div class="finance-grid"><form class="panel" onsubmit="createCommissionRule(event)"><h2>قاعدة عمولة مرنة</h2><label>طريقة الحساب<select id="commissionType"><option value="percentage">نسبة مئوية</option><option value="fixed">مبلغ ثابت</option></select></label><label>القيمة<input id="commissionValue" type="number" min="0" step="0.01" required></label><label>المدينة (اختياري)<select id="commissionCity"><option value="">كل المدن</option></select></label><label>تصنيف المحل (اختياري)<input id="commissionCategory" placeholder="مثال: مطعم"></label><label>حد أدنى (اختياري)<input id="commissionMin" type="number" min="0" step="0.01" value="0"></label><label>حد أقصى (اختياري)<input id="commissionMax" type="number" min="0" step="0.01"></label><button class="primary">حفظ وتفعيل القاعدة</button></form><section class="panel"><div class="panel-head"><h2>القواعد الحالية</h2><button onclick="loadCommissionRules()">↻ تحديث</button></div><div id="commissionRules"></div></section></div>`;
 document.getElementById('admin-approvals').insertAdjacentHTML('afterbegin','<div class="panel" style="margin-bottom:16px"><div class="panel-head"><div><h2>طلبات مشرفي المدن</h2><p>إضافة المحل أو المندوب لا تصبح معتمدة إلا من هنا.</p></div><button onclick="loadPartnerApprovals()">↻ تحديث</button></div><div id="partnerApprovals"></div></div>');
 window.staffLogout=()=>{localStorage.removeItem('khalasaStaffToken');location.reload()};
 window.loadMainAdmins=async()=>{const r=await fetch(`${api}/v1/admin/main-users`,{headers:headers()});if(!r.ok)return;const data=await r.json();mainAdminsList.innerHTML=data.users.map(x=>`<article class="city-user-card"><div><b>${esc(x.full_name)}</b><small>${esc(x.phone)}</small></div><button class="table-btn" onclick="toggleMainAdmin('${x.id}',${!x.is_active})">${x.is_active?'تعطيل':'تفعيل'}</button></article>`).join('')};
 window.createMainAdmin=async e=>{e.preventDefault();const r=await fetch(`${api}/v1/admin/main-users`,{method:'POST',headers:headers(),body:JSON.stringify({fullName:mainAdminName.value.trim(),phone:mainAdminPhone.value.trim(),accessCode:mainAdminCode.value})});if(!r.ok)return toast('تعذر منح الصلاحية؛ تحقق من البيانات');e.target.reset();toast('تم منح صلاحية الإدارة الرئيسية');loadMainAdmins()};
 window.toggleMainAdmin=async(id,isActive)=>{const r=await fetch(`${api}/v1/admin/main-users/${id}`,{method:'PATCH',headers:headers(),body:JSON.stringify({isActive})});toast(r.ok?'تم تحديث الصلاحية':'لا يمكن تعطيل هذا المستخدم');if(r.ok)loadMainAdmins()};
 window.loadCommissionRules=async()=>{const [rr,cr]=await Promise.all([fetch(`${api}/v1/admin/commission-rules`,{headers:headers()}),fetch(`${api}/v1/admin/cities`,{headers:headers()})]);if(!rr.ok)return;const rules=(await rr.json()).rules||[];if(cr.ok){const cities=(await cr.json()).cities||[];commissionCity.innerHTML='<option value="">كل المدن</option>'+cities.map(x=>`<option value="${x.id}">${esc(x.governorate)} — ${esc(x.name)}</option>`).join('')}commissionRules.innerHTML=rules.length?rules.map(x=>`<article class="city-user-card"><div><b>${x.calculation_type==='percentage'?`${x.value}%`:`${x.value} ج.م ثابت`}</b><small>${esc(x.city_name||'كل المدن')} · ${esc(x.merchant_category||'كل التصنيفات')}</small><small>الحد الأدنى ${x.minimum_amount||0}${x.maximum_amount!=null?` · الأقصى ${x.maximum_amount}`:''}</small></div><button class="table-btn" onclick="toggleCommission('${x.id}',${!x.is_active})">${x.is_active?'إيقاف':'تفعيل'}</button></article>`).join(''):'<p>لا توجد قواعد؛ تُستخدم النسبة الافتراضية.</p>'};
 window.createCommissionRule=async e=>{e.preventDefault();const r=await fetch(`${api}/v1/admin/commission-rules`,{method:'POST',headers:headers(),body:JSON.stringify({calculationType:commissionType.value,value:Number(commissionValue.value),cityId:commissionCity.value,merchantCategory:commissionCategory.value.trim(),minimumAmount:Number(commissionMin.value||0),maximumAmount:commissionMax.value})});if(!r.ok)return toast('تعذر حفظ قاعدة العمولة');e.target.reset();commissionMin.value=0;toast('تم تفعيل قاعدة العمولة');loadCommissionRules()};
 window.toggleCommission=async(id,isActive)=>{const r=await fetch(`${api}/v1/admin/commission-rules/${id}`,{method:'PATCH',headers:headers(),body:JSON.stringify({isActive})});toast(r.ok?'تم تحديث القاعدة':'تعذر تحديث القاعدة');if(r.ok)loadCommissionRules()};
 window.loadPartnerApprovals=async()=>{const r=await fetch(`${api}/v1/admin/partner-requests`,{headers:headers()});if(!r.ok)return;const data=await r.json();partnerApprovals.innerHTML=(data.requests||[]).map(x=>`<article class="city-user-card"><div><b>${esc(x.full_name)} — ${x.partner_type==='rider'?'مندوب':'محل'}</b><small>${esc(x.city_name)} · ${esc(x.phone)} · بواسطة ${esc(x.requester_name)}</small><span class="tag">${x.status==='pending'?'بانتظار موافقتك':x.status==='approved'?'مقبول':'مرفوض'}</span></div>${x.status==='pending'?`<div><button class="approve" onclick="reviewPartner('${x.id}','approved')">موافقة</button><button class="decline" onclick="reviewPartner('${x.id}','rejected')">رفض</button></div>`:''}</article>`).join('')||'<p>لا توجد طلبات من المدن.</p>'};
 window.reviewPartner=async(id,status)=>{const r=await fetch(`${api}/v1/admin/partner-requests/${id}`,{method:'PATCH',headers:headers(),body:JSON.stringify({status})});toast(r.ok?(status==='approved'?'تمت الموافقة':'تم الرفض'):'تعذر تحديث الطلب');if(r.ok)loadPartnerApprovals()};
 const oldAdminPage=window.adminPage;window.adminPage=function(page,button){oldAdminPage(page,button);if(page==='finance')loadCommissionRules();if(page==='approvals')loadPartnerApprovals()};
})();
